function safeStore(name){
  try { const s=window[name]; s.getItem('__canvas_probe__'); return s; }
  catch { let d={}; return {getItem:k=>Object.prototype.hasOwnProperty.call(d,k)?d[k]:null,setItem:(k,v)=>{d[k]=String(v)},removeItem:k=>{delete d[k]},clear:()=>{d={}}}; }
}
const LS=safeStore('localStorage'), SS=safeStore('sessionStorage');

const clone = (v) => typeof structuredClone === 'function' ? structuredClone(v) : JSON.parse(JSON.stringify(v));

