  view: { x: innerWidth / 2, y: innerHeight / 2, scale: 1 },
  busy:false, listening:false, shouldListen:false, activeTool:'select', connectSource:null, connectArrow:false,
  multiSelect:false, preset:'pastel', projectId:'', projectName:'Untitled', collabRoom:'', lastSync:0,
  searchQuery:'', dragMutationSaved:false, focusRoot:null, collapsed:new Set(),
  filter:{kind:'all',sources:false,status:'all'}, presentation:{active:false,index:0,order:[]},
