function addNode(data,label='إضافة عنصر'){ mutate(label,()=>{const n=normalizeNode(data);state.nodes.push(n);state.selectedIds.clear();state.selectedIds.add(n.id);}); return [...state.selectedIds][0]; }
function deleteSelected(){const ids=[...state.selectedIds];if(!ids.length)return;mutate(ids.length>1?'حذف عناصر':'حذف عنصر',()=>{state.nodes=state.nodes.filter(n=>!ids.includes(n.id));state.edges=state.edges.filter(e=>!ids.includes(e.from)&&!ids.includes(e.to));state.groups=state.groups.map(g=>({...g})).filter(g=>state.nodes.some(n=>n.groupId===g.id));state.selectedIds.clear();});}
