function layoutRoot(){const deg=new Map(state.nodes.map(n=>[n.id,0]));state.edges.forEach(e=>{deg.set(e.from,(deg.get(e.from)||0)+1);deg.set(e.to,(deg.get(e.to)||0)+1);});return[...state.nodes].sort((a,b)=>(deg.get(b.id)||0)-(deg.get(a.id)||0))[0]||state.nodes[0];}
