function autoLayoutNoHistory(){if(!state.nodes.length)return;const chain=state.edges.length>=Math.max(1,state.nodes.length-1);if(chain&&state.nodes.length>3)treeLayoutNoHistory(innerWidth<650?'vertical':'horizontal');else radialLayoutNoHistory();state.selectedIds.clear();}
function applyLayout(mode='auto',direction='vertical'){if(!state.nodes.length)return;mutate(`ترتيب ${mode}`,()=>{if(mode==='linear')linearLayoutNoHistory(direction);else if(mode==='grid')gridLayoutNoHistory();else if(mode==='tree'||mode==='hierarchy'||mode==='org')treeLayoutNoHistory(direction);else if(mode==='timeline')timelineLayoutNoHistory();else if(mode==='flow')flowLayoutNoHistory(direction);else if(mode==='dependency'){state.edges.forEach(e=>e.arrow=true);flowLayoutNoHistory(direction);}else if(mode==='radial')radialLayoutNoHistory();else autoLayoutNoHistory();});fitToContent(34,1);}
function autoLayout(){applyLayout('auto');}function linearLayout(direction='vertical'){applyLayout('linear',direction);}
function centerOnNode(id){const n=state.nodes.find(x=>x.id===id);if(!n)return;const s=sizeFor(n);state.view.x=innerWidth/2-(n.x+s.w/2)*state.view.scale;state.view.y=(innerHeight-80)/2-(n.y+s.h/2)*state.view.scale;state.selectedIds.clear();state.selectedIds.add(id);applyView();render();}
function fitToContent(padding=34,maxScale=1){if(!state.nodes.length)return;const visible=state.nodes.filter(n=>visibleNodeIds().has(n.id));if(!visible.length)return;const boxes=visible.map(n=>{const sz=sizeFor(n);return{x:n.x,y:n.y,w:sz.w,h:sz.h}}),minX=Math.min(...boxes.map(b=>b.x)),minY=Math.min(...boxes.map(b=>b.y)),maxX=Math.max(...boxes.map(b=>b.x+b.w)),maxY=Math.max(...boxes.map(b=>b.y+b.h)),cw=Math.max(1,maxX-minX),ch=Math.max(1,maxY-minY),availW=Math.max(180,innerWidth-padding*2),availH=Math.max(230,innerHeight-270),scale=Math.min(maxScale,availW/cw,availH/ch);state.view.scale=Math.max(.18,scale);const cx=(minX+maxX)/2,cy=(minY+maxY)/2;state.view.x=innerWidth/2-cx*state.view.scale;state.view.y=(innerHeight-90)/2-cy*state.view.scale;applyView();scheduleSave();}

function renderSuggestions(){if(document.activeElement!==commandInput&&state.selectedIds.size===0){suggestionsEl.innerHTML='';return;}const suggestions=[];if(state.selectedIds.size===1){suggestions.push(['كبّر هاي','كبّر هاي'],['غيّر اللون','لونها أزرق'],['اربط هاي','اربط هاي بـ ']);}else if(!state.nodes.length){suggestions.push(['خريطة أفكار','سويلي خريطة أفكار لمشروع جديد'],['Flowchart','سوي flowchart بسيط']);}else{suggestions.push(['بحث ويب','ابحث بالويب عن '],['خطط','سويلي خطة كاملة لـ '],['رتّب','رتب العناصر تلقائياً'],['حلّل','راجع الخطة واكتشف النواقص']);} suggestionsEl.innerHTML=suggestions.map(([a,v])=>`<button class="suggestion" data-value="${escapeAttr(v)}">${a}</button>`).join(''); $$('.suggestion',suggestionsEl).forEach(b=>b.onclick=()=>{commandInput.value=b.dataset.value;resizeInput();commandInput.focus();});}
function escapeAttr(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');}

function tryLocalCommand(text){
  const t=text.trim();if(/^(تراجع|ارجع|رجع خطوة|undo)$/i.test(t)){undo();return true;}if(/^(اعادة|إعادة|redo)$/i.test(t)){redo();return true;}
  if(/رتب|رتّب|نظّم|نظم|arrange|layout|linearly|linear|شجري|هرمي|دائري|شبكي|timeline|flowchart|org chart/i.test(t)){
    const dir=/أفقي|افقي|horizontal/i.test(t)?'horizontal':'vertical'; if(/خطي|خط واحد|سطر واحد|linearly|linear/i.test(t))applyLayout('linear',dir);else if(/شبك|grid/i.test(t))applyLayout('grid');else if(/شجري|tree/i.test(t))applyLayout('tree',dir);else if(/هرمي|hierarchy|org/i.test(t))applyLayout('hierarchy',dir);else if(/timeline|زمني|زمن/i.test(t))applyLayout('timeline');else if(/اعتماد|dependenc/i.test(t))applyLayout('dependency',dir);else if(/flow/i.test(t))applyLayout('flow',dir);else if(/دائري|radial/i.test(t))applyLayout('radial');else autoLayout();return true;
  }
  if(/احذف (هاي|هذا|المحدد)|delete selected/i.test(t)){deleteSelected();return true;}if(/امسح (الكل|كلشي)|clear all/i.test(t)){mutate('مسح اللوحة',()=>{state.nodes=[];state.edges=[];state.groups=[];state.selectedIds.clear();});return true;}if(/احفظ/i.test(t)){saveCurrentProject(true);return true;}if(/اعتماد|dependencies|dependency/i.test(t)){applyLayout('dependency',innerWidth<650?'vertical':'horizontal');return true;}if(/حول|حوّل/i.test(t)&&/جدول|table/i.test(t)){convertCanvasToTable();return true;}
  let m=t.match(/(?:روح|اذهب|انتقل|ركز|ركّز)\s*(?:على|الى|إلى)?\s*(.+)/i);if(m){const id=resolveNodeId(m[1]);if(id){centerOnNode(id);return true;}}
  if(/focus|وضع التركيز|ركز على المحدد/i.test(t)&&state.selectedIds.size===1){state.focusRoot=[...state.selectedIds][0];render();fitToContent();return true;}
  if(/الغاء التركيز|إلغاء التركيز|اظهر الكل|أظهر الكل/i.test(t)){state.focusRoot=null;state.collapsed.clear();render();fitToContent();return true;}
  if(/اطوي|طي الفرع|collapse/i.test(t)&&state.selectedIds.size===1){state.collapsed.add([...state.selectedIds][0]);render();return true;}if(/افتح الفرع|وسع الفرع|expand/i.test(t)&&state.selectedIds.size===1){state.collapsed.delete([...state.selectedIds][0]);render();return true;}
  const sel=state.selectedIds.size===1?state.nodes.find(n=>state.selectedIds.has(n.id)):null;
  m=t.match(/(?:كرر|انسخ|duplicate)\s*(?:هاي|هذا|المحدد)?\s*(\d+)?/i);if(m&&sel){duplicateNode(sel.id,Math.min(10,Number(m[1]||1)));return true;}
  m=t.match(/(?:سوي|انشئ|أنشئ|اضف|أضف)\s*(?:لي\s*)?(دائرة|مربع|بطاقة|نص|ملاحظة|مهمة|جدول|تشيك ليست|قائمة|رابط)\s*(?:باسم|اسمها)?\s*(.+)?/i);if(m){const kindWord=m[1],label=(m[2]||'عنصر').trim(),shape=/دائرة/.test(kindWord)?'circle':/نص/.test(kindWord)?'text':/ملاحظة/.test(kindWord)?'sticky':'rounded',kind=/مهمة/.test(kindWord)?'task':/جدول/.test(kindWord)?'table':/تشيك|قائمة/.test(kindWord)?'checklist':/رابط/.test(kindWord)?'link':'basic';addNode({shape,kind,label},`إضافة ${kindWord}`);return true;}
  if(sel){m=t.match(/(?:غير|غيّر)\s*(?:اسمها|اسم|النص)\s*(?:إلى|الى)?\s*(.+)/i);if(m){mutate('تغيير الاسم',()=>sel.label=m[1].trim().slice(0,220));return true;}if(/كبر|كبّر|make it bigger/i.test(t)){mutate('تكبير عنصر',()=>sel.size=sel.size==='s'?'m':'l');return true;}if(/صغر|صغّر/i.test(t)){mutate('تصغير عنصر',()=>sel.size=sel.size==='l'?'m':'s');return true;}const cmap={أزرق:'blue',ازرق:'blue',أخضر:'green',اخضر:'green',أحمر:'pink',احمر:'pink',وردي:'pink',بنفسجي:'purple',أصفر:'yellow',اصفر:'yellow',برتقالي:'orange',رمادي:'gray'};for(const[word,c]of Object.entries(cmap)){if(t.includes(word)){mutate('تغيير اللون',()=>sel.color=c);return true;}}m=t.match(/(?:اربط|وصل)\s*(?:هاي|هذا|المحدد)?\s*(?:بـ|ب|مع)\s*(.+)/i);if(m){const to=resolveNodeId(m[1]);if(to&&to!==sel.id){mutate('ربط عنصرين',()=>state.edges.push({id:uid('e'),from:sel.id,to,arrow:false,label:''}));return true;}}}
  return false;
}
function duplicateNode(id,count=1){const src=state.nodes.find(n=>n.id===id);if(!src)return;mutate('تكرار عنصر',()=>{for(let i=0;i<count;i++){const n=normalizeNode({...clone(src),id:uid('node'),x:src.x+42*(i+1),y:src.y+42*(i+1),label:count>1?`${src.label} ${i+1}`:src.label});state.nodes.push(n);}});}
function convertCanvasToTable(){if(!state.nodes.length)return;mutate('تحويل إلى جدول',()=>{const rows=[['العنصر','النوع','الحالة'],...state.nodes.slice(0,30).map(n=>[n.label,n.kind||n.shape,n.status||'—'])],c=viewportCenterWorld(),tbl=normalizeNode({label:'ملخص اللوحة',shape:'rounded',kind:'table',table:rows,color:'blue',x:c.x-110,y:c.y-120,note:`${state.nodes.length} عنصر · ${state.edges.length} علاقة`});state.nodes.push(tbl);state.selectedIds.clear();state.selectedIds.add(tbl.id);});centerOnNode([...state.selectedIds][0]);}
function groupNodesByIds(ids,name='مجموعة'){const valid=ids.map(resolveNodeId).filter(Boolean);if(valid.length<2)return;const gid=uid('group');state.groups.push({id:gid,name});state.nodes.forEach(n=>{if(valid.includes(n.id))n.groupId=gid;});}

function routeCommand(text){const t=text.trim();if(/https?:\/\//i.test(t)&&/(اقرأ|اقرا|حلل|لخص|الرابط|صفحة|url|link)/i.test(t))return'url';if(/github|جيت ?هب|مفتوح المصدر|repository|repo/i.test(t))return'github';if(/صور|صورة|image references|مراجع بصرية/i.test(t))return'images';if(/اخبار|أخبار|news|اخر التطورات|آخر التطورات/i.test(t))return'news';if(/منافس|competitor|شركات مشابه/i.test(t))return'competitors';if(/قارن|مقارنة|compare/i.test(t)){if(state.selectedIds.size>=2&&!/(اداة|أداة|منصة|tool|vs|بين)/i.test(t))return'compare-canvas';return'compare-tools';}if(/(?:افضل|أفضل|انسب|أنسب|اختار|اختر).*(?:أداة|اداة|خدمة|backend|database|استضافة|hosting|tool)|tool finder|شنو نحتاج من أدوات|شنو نحتاج من ادوات/i.test(t))return'toolfinder';if(/تكلفة|كلفة|ميزانية|cost|سعر التشغيل/i.test(t)&&!/خطة|plan/i.test(t))return'cost';if(/وثائق|توثيق|documentation|docs/i.test(t))return'docs';if(/api\s*https?:\/\//i.test(t)||/(اختبر|جرب).*api/i.test(t))return'api';if(/شغل.*كود|نفذ.*كود|run code|احسب.*بايثون|python/i.test(t))return'code';if(/حد[ثّ].*الخطة|update.*plan/i.test(t))return'update-plan';if(/راجع.*الخطة|انتقد|نواقص|critic/i.test(t))return'critic';if(/لخص.*اللوحة|summarize.*canvas/i.test(t))return'summarize';if(/وسع.*المحدد|فصل.*المحدد|expand selected/i.test(t))return'expand';if(/اسأل.*اللوحة|اسال.*اللوحة|ask canvas/i.test(t))return'ask-canvas';if(/حول|حوّل|convert/i.test(t)&&/(جدول|table|flowchart|timeline|زمني|خريطة)/i.test(t))return'convert';if(/سويلي خطة|اعمل.*خطة|خطط.*(?:منصة|تطبيق|مشروع|شركة|منتج)|plan.*(?:platform|app|project)/i.test(t))return'plan';if(/بحث عميق|deep research/i.test(t))return'deep';if(/ابحث|بحث عن|research|search web|دور على/i.test(t))return'web';return'canvas';}

async function submitCommand(textOverride=''){
  const text=(textOverride||commandInput.value).trim();if(!text||state.busy)return;commandInput.value='';interimText.textContent='';interimText.classList.remove('visible');state.livePreview='';resizeInput();if(tryLocalCommand(text)){setStatus('تم','ok');setTimeout(()=>setStatus('جاهز'),800);return;}
  if(!settings.apiKey){openSettings();toast('ضيف مفتاح Gemini أولاً');commandInput.value=text;resizeInput();return;}
  state.busy=true;sendBtn.disabled=true;const route=routeCommand(text);setStatus(route==='canvas'?'أفهم الأمر…':'أستخدم الأدوات…','thinking');
  try{let payload;if(route==='canvas')payload=await askGemini(text);else{await runAgentRoute(route,text);setStatus('تم','ok');return;}const actions=sanitizeActions(payload);if(!actions.length)throw new Error('Gemini لم يرجع أوامر رسم صالحة');executeActions(actions);setStatus('تم','ok');if(payload.message)toast(payload.message);}catch(err){console.error(err);setStatus('خطأ');toast(friendlyError(err));}finally{state.busy=false;sendBtn.disabled=false;setTimeout(()=>{if(!state.listening&&!state.busy)setStatus('جاهز');},900);}
}

const ACTION_SCHEMA={type:'object',properties:{actions:{type:'array',items:{type:'object',properties:{type:{type:'string',enum:['add_node','connect','update_node','move_node','delete_node','clear','auto_layout','linear_layout','layout','group_nodes']},id:{type:'string'},from:{type:'string'},to:{type:'string'},label:{type:'string'},shape:{type:'string',enum:['circle','rounded','text','sticky','image']},kind:{type:'string'},x:{type:'number'},y:{type:'number'},color:{type:'string'},size:{type:'string'},icon:{type:'string'},note:{type:'string'},arrow:{type:'boolean'},direction:{type:'string'},layout:{type:'string'},url:{type:'string'},source:{type:'string'},reason:{type:'string'},alternatives:{type:'string'},cost:{type:'string'},confidence:{type:'number'},tags:{type:'array',items:{type:'string'}},status:{type:'string'},progress:{type:'number'},checklist:{type:'array',items:{type:'string'}},table:{type:'array',items:{type:'array',items:{type:'string'}}},ids:{type:'array',items:{type:'string'}},name:{type:'string'}},required:['type']}},message:{type:'string'}},required:['actions']};
function sanitizeActions(p){return p&&Array.isArray(p.actions)?p.actions.slice(0,100).filter(a=>a&&typeof a.type==='string'):[];}
function executeActions(actions){if(!actions.length)return;pushUndo();let newCount=0;for(const a of actions){if(a.type==='clear'){state.nodes=[];state.edges=[];state.groups=[];state.selectedIds.clear();continue;}if(a.type==='auto_layout'){autoLayoutNoHistory();continue;}if(a.type==='linear_layout'){linearLayoutNoHistory(a.direction||'vertical');continue;}if(a.type==='layout'){const m=a.layout||'auto';if(m==='grid')gridLayoutNoHistory();else if(['tree','hierarchy','org'].includes(m))treeLayoutNoHistory(a.direction||'vertical');else if(m==='timeline')timelineLayoutNoHistory();else if(m==='flow')flowLayoutNoHistory(a.direction||'vertical');else if(m==='radial')radialLayoutNoHistory();else autoLayoutNoHistory();continue;}if(a.type==='group_nodes'){groupNodesByIds(a.ids||[],a.name||'مجموعة');continue;}if(a.type==='add_node'){const n=normalizeNode(a,newCount++);state.nodes.push(n);state.selectedIds.clear();state.selectedIds.add(n.id);continue;}if(a.type==='connect'){const from=resolveNodeId(a.from),to=resolveNodeId(a.to);if(from&&to&&from!==to&&!state.edges.some(e=>e.from===from&&e.to===to&&e.label===(a.label||'')))state.edges.push({id:uid('e'),from,to,label:a.label||'',arrow:!!a.arrow,relation:a.label||''});continue;}const id=resolveNodeId(a.id),n=state.nodes.find(x=>x.id===id);if(!n)continue;if(a.type==='update_node'){for(const k of ['label','note','url','source','reason','alternatives','cost','status','kind'])if(typeof a[k]==='string'&&a[k].trim())n[k]=a[k].trim().slice(0,k==='label'?220:1200);if(['circle','rounded','text','sticky','image'].includes(a.shape))n.shape=a.shape;if(COLOR_KEYS.includes(a.color))n.color=a.color;if(['s','m','l'].includes(a.size))n.size=a.size;if(typeof a.icon==='string')n.icon=a.icon.slice(0,8);if(Number.isFinite(Number(a.confidence)))n.confidence=Math.max(0,Math.min(1,Number(a.confidence)));if(Number.isFinite(Number(a.progress)))n.progress=Math.max(0,Math.min(100,Number(a.progress)));if(Array.isArray(a.tags))n.tags=a.tags.map(String).slice(0,8);if(Array.isArray(a.checklist))n.checklist=a.checklist.slice(0,12).map(x=>({text:String(x),done:false}));if(Array.isArray(a.table))n.table=a.table.slice(0,8);}else if(a.type==='move_node'){if(Number.isFinite(a.x))n.x=a.x;if(Number.isFinite(a.y))n.y=a.y;}else if(a.type==='delete_node'){state.nodes=state.nodes.filter(x=>x.id!==id);state.edges=state.edges.filter(e=>e.from!==id&&e.to!==id);state.selectedIds.delete(id);}}
  finishMutation('تنفيذ أمر AI',`${actions.length} actions`);if(actions.length>=4)fitToContent(34,1);
}
function compactCanvasState(){return{nodes:state.nodes.map(n=>({id:n.id,label:n.label,shape:n.shape,kind:n.kind,color:n.color,size:n.size,note:n.note,url:n.url,source:n.source,status:n.status,x:Math.round(n.x),y:Math.round(n.y)})),edges:state.edges.map(e=>({from:e.from,to:e.to,label:e.label,arrow:e.arrow})),selectedIds:[...state.selectedIds],viewportCenter:Object.fromEntries(Object.entries(viewportCenterWorld()).map(([k,v])=>[k,Math.round(v)]))};}
const MODEL_PREFERENCE=['gemini-3.5-flash-lite','gemini-3.1-flash-lite','gemini-2.5-flash-lite','gemini-3.6-flash','gemini-3.5-flash','gemini-2.5-flash'];const TOOL_MODEL_PREFERENCE=['gemini-3.6-flash','gemini-3.5-flash','gemini-3.5-flash-lite','gemini-3.1-flash-lite','gemini-2.5-flash'];let modelCache={key:'',models:[],at:0};
async function listAvailableModels(force=false){if(!settings.apiKey)throw new Error('اكتب مفتاح Gemini API أولاً');const now=Date.now();if(!force&&modelCache.key===settings.apiKey&&modelCache.models.length&&now-modelCache.at<300000)return modelCache.models;const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),12000);let res;try{res=await fetch('https://generativelanguage.googleapis.com/v1beta/models?pageSize=100',{headers:{'x-goog-api-key':settings.apiKey},signal:ctrl.signal});}finally{clearTimeout(timer);}const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data?.error?.message||`Gemini Models API ${res.status}`);const models=(data.models||[]).filter(m=>Array.isArray(m.supportedGenerationMethods)&&m.supportedGenerationMethods.includes('generateContent')).map(m=>String(m.name||'').replace(/^models\//,'')).filter(Boolean);if(!models.length)throw new Error('هذا المفتاح ما رجّع أي موديل يدعم generateContent');modelCache={key:settings.apiKey,models,at:now};return models;}
function choosePreferredModel(models,requested='auto'){const clean=String(requested||'auto').replace(/^models\//,'').trim();if(clean&&clean!=='auto'&&models.includes(clean))return clean;return MODEL_PREFERENCE.find(m=>models.includes(m))||models.find(m=>/flash-lite/i.test(m))||models.find(m=>/flash/i.test(m))||models[0];}
async function resolveModel(force=false){const models=await listAvailableModels(force),model=choosePreferredModel(models,settings.model);settings.resolvedModel=model;modelPillText.textContent=prettyModelName(model);return model;}
async function resolveToolModel(){const models=await listAvailableModels(false);return TOOL_MODEL_PREFERENCE.find(m=>models.includes(m))||models.find(m=>/flash/i.test(m))||models[0];}
async function requestGemini(model,body,timeout=30000){const url=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),timeout);let res;try{res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':settings.apiKey},body:JSON.stringify(body),signal:ctrl.signal});}finally{clearTimeout(timer);}const data=await res.json().catch(()=>({}));if(!res.ok){const e=new Error(data?.error?.message||`Gemini API ${res.status}`);e.status=res.status;e.model=model;throw e;}return data;}
function geminiText(data){return data?.candidates?.[0]?.content?.parts?.map(p=>p.text||p.codeExecutionResult?.output||'').filter(Boolean).join('\n')||'';}
function parseGeminiJson(data){const text=geminiText(data);if(!text)throw new Error('رد Gemini فارغ');try{return JSON.parse(text);}catch{return JSON.parse(text.replace(/^```json\s*/i,'').replace(/```$/,'').trim());}}
function extractSources(data){const out=[],seen=new Set(),c=data?.candidates?.[0]||{},chunks=c.groundingMetadata?.groundingChunks||[];for(const ch of chunks){const w=ch?.web;if(w?.uri&&!seen.has(w.uri)){seen.add(w.uri);out.push({url:w.uri,title:w.title||safeHost(w.uri)});}}const meta=c.urlContextMetadata?.urlMetadata||c.url_context_metadata?.url_metadata||[];for(const u of meta){const url=u.retrievedUrl||u.retrieved_url||u.url;if(url&&!seen.has(url)){seen.add(url);out.push({url,title:safeHost(url)});}}return out.slice(0,20);}
async function askGemini(userText){const system=`أنت محرك أوامر لمساحة عمل بصرية ذكية. أرجع JSON فقط وفق المخطط.\n- الأشكال: circle, rounded, text, sticky. الأنواع الغنية kind: basic, card, table, checklist, link, file, progress, source, task.\n- الألوان: blue green pink purple yellow mint orange gray.\n- افهم هاي/هذا/اللي فوق من selectedIds والمواقع.\n- العلاقات تكون لها label مثل يعتمد على، يسبب، قبل، بعد، جزء من.
- إذا طلب المستخدم جمع العناصر المتشابهة استخدم group_nodes مع ids وname.\n- استخدم layout بقيم radial/grid/tree/hierarchy/timeline/flow/org/auto عندما يطلب المستخدم شكلاً محدداً.\n- يمكنك إنشاء خطة كاملة حتى 45 عنصراً مع أسباب واختيارات وأدوات ومراحل.\n- إذا المعلومة ناتجة من مصدر مرر url/source/confidence.\n- نفّذ أقل actions معقولة وmessage عربية قصيرة.`;const body={systemInstruction:{parts:[{text:system}]},contents:[{role:'user',parts:[{text:`الحالة الحالية:\n${JSON.stringify(compactCanvasState())}\n\nطلب المستخدم:\n${userText}`}]}],generationConfig:{maxOutputTokens:7000,responseMimeType:'application/json',responseJsonSchema:ACTION_SCHEMA}};let model=await resolveModel();try{return parseGeminiJson(await requestGemini(model,body,50000));}catch(first){if(![400,404].includes(first.status))throw first;const models=await listAvailableModels(true);for(const m of models.filter(x=>/flash/i.test(x)&&x!==model).slice(0,6)){try{settings.resolvedModel=m;return parseGeminiJson(await requestGemini(m,body,50000));}catch(e){if(![400,404].includes(e.status))throw e;}}throw first;}}
async function groundedSearch(prompt){const model=await resolveToolModel(),body={contents:[{role:'user',parts:[{text:prompt}]}],tools:[{google_search:{}}],generationConfig:{maxOutputTokens:5000}};const data=await requestGemini(model,body,60000);return{text:geminiText(data),sources:extractSources(data),raw:data};}
async function urlContextRead(url,prompt=''){const model=await resolveToolModel(),body={contents:[{role:'user',parts:[{text:`اقرأ هذا الرابط واعتمد على محتواه فقط قدر الإمكان: ${url}\n${prompt||'لخص أهم المعلومات والبيانات والادعاءات مع ما يفيد التخطيط.'}`}]}],tools:[{url_context:{}}],generationConfig:{maxOutputTokens:5000}};const data=await requestGemini(model,body,60000);return{text:geminiText(data),sources:[{url,title:safeHost(url)},...extractSources(data)]};}
async function codeExecution(prompt){const model=await resolveToolModel(),body={contents:[{role:'user',parts:[{text:prompt}]}],tools:[{code_execution:{}}],generationConfig:{maxOutputTokens:4000}};const data=await requestGemini(model,body,60000),parts=data?.candidates?.[0]?.content?.parts||[];return{text:geminiText(data),code:parts.find(p=>p.executableCode)?.executableCode?.code||'',output:parts.find(p=>p.codeExecutionResult)?.codeExecutionResult?.output||''};}
async function researchToCanvas(title,researchText,sources=[],instruction=''){const src=sources.slice(0,12).map((x,i)=>`[${i+1}] ${x.title||''} ${x.url}`).join('\n');const payload=await askGemini(`حوّل البحث التالي إلى خريطة بصرية عملية ومنظمة. ${instruction}\nالعنوان: ${title}\nالمصادر:\n${src}\n\nالمحتوى:\n${researchText}\n\nلكل عقدة مبنية على مصدر ضع url وsource وconfidence. أنشئ عقد مصادر منفصلة عند الحاجة ثم استخدم layout مناسب.`);const actions=sanitizeActions(payload);if(!actions.length)throw new Error('تعذر تحويل البحث إلى خريطة');executeActions(actions);state.researchContext={title,text:researchText,sources,updatedAt:Date.now()};return payload;}
async function runDeepResearch(topic,kind='research'){setStatus('أبحث من عدة زوايا…','thinking');const queries=kind==='plan'?[`ابحث حديثاً عن أفضل طريقة عملية لبناء ${topic}. ركز على المعمارية والأدوات الحالية وخيارات التقنية والتكلفة.`,`ابحث عن المنافسين/البدائل والمخاطر والأخطاء الشائعة عند تنفيذ ${topic}.`,`ابحث عن أفضل الأدوات والخدمات الحالية اللازمة لـ ${topic} مع أسباب الاختيار والأسعار أو الخطط المجانية إن أمكن.`]:[`ابحث عن ${topic}: الحقائق الأساسية وأحدث المعلومات من مصادر موثوقة.`,`ابحث عن ${topic}: آراء أو زوايا مختلفة، أرقام، مقارنات ومخاطر.`,`ابحث عن ${topic}: مصادر أولية أو رسمية وتفاصيل قابلة للتحقق.`];const results=[];for(let i=0;i<queries.length;i++){setStatus(`بحث ${i+1}/${queries.length}…`,'thinking');results.push(await groundedSearch(queries[i]));}const sources=[],seen=new Set();for(const r of results)for(const x of r.sources)if(x.url&&!seen.has(x.url)){seen.add(x.url);sources.push(x);}const text=results.map((r,i)=>`زاوية ${i+1}:\n${r.text}`).join('\n\n');await researchToCanvas(topic,text,sources,kind==='plan'?'اجعل الخريطة خطة تنفيذ كاملة: مراحل، أدوات محددة، معمارية، تكلفة، مخاطر، بدائل، ومخرجات. لا تذكر أداة بلا سبب.':'اجعل الخريطة تجمع النتائج والأدلة والمصادر بشكل واضح.');return{sources,text};}
async function runGithubSearch(query){setStatus('أبحث في GitHub…','thinking');const res=await fetch(`https://api.github.com/search/repositories?q=${encodeURIComponent(query)}&sort=stars&order=desc&per_page=8`,{headers:{Accept:'application/vnd.github+json'}}),data=await res.json();if(!res.ok)throw new Error(data?.message||`GitHub ${res.status}`);const items=(data.items||[]).slice(0,8);mutate('بحث GitHub',()=>{const c=viewportCenterWorld(),root=normalizeNode({label:`GitHub: ${query}`,shape:'circle',color:'blue',icon:'⌘',kind:'source',x:c.x-70,y:c.y-70});state.nodes.push(root);items.forEach((r,i)=>{const n=normalizeNode({label:r.full_name,shape:'rounded',kind:'source',color:DEFAULT_COLORS[i%DEFAULT_COLORS.length],note:(r.description||'').slice(0,260),url:r.html_url,source:'GitHub',reason:`★ ${r.stargazers_count?.toLocaleString?.()||r.stargazers_count||0} · ${r.language||'—'}`,confidence:.95});state.nodes.push(n);state.edges.push({id:uid('e'),from:root.id,to:n.id,label:'repo',arrow:false});});gridLayoutNoHistory();});fitToContent();return items;}
async function runImageSearch(query){setStatus('أبحث عن مراجع بصرية…','thinking');const url=`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(query)}&gsrnamespace=6&gsrlimit=8&prop=imageinfo&iiprop=url|extmetadata&format=json&origin=*`,res=await fetch(url),data=await res.json();const pages=Object.values(data.query?.pages||{}).slice(0,8);if(!pages.length)throw new Error('ما لقيت صور');mutate('بحث صور',()=>{const c=viewportCenterWorld(),root=normalizeNode({label:`مراجع: ${query}`,shape:'circle',color:'blue',icon:'▧',kind:'source',x:c.x-70,y:c.y-70});state.nodes.push(root);pages.forEach((p,i)=>{const info=p.imageinfo?.[0]||{},img=info.thumburl||info.url,n=normalizeNode({label:String(p.title||'').replace(/^File:/,''),shape:'image',kind:'source',image:img,url:info.descriptionurl||info.url,source:'Wikimedia Commons',color:'gray',confidence:.98});state.nodes.push(n);state.edges.push({id:uid('e'),from:root.id,to:n.id,label:'مرجع',arrow:false});});gridLayoutNoHistory();});fitToContent();return pages;}
async function runApiTestFromText(text){const u=(text.match(/https?:\/\/[^\s]+/i)||[])[0];if(!u)throw new Error('اكتب رابط API');setStatus('أختبر API…','thinking');const t=performance.now();let res,body;try{res=await fetch(u,{headers:{Accept:'application/json,text/plain,*/*'}});body=await res.text();}catch(e){throw new Error(`تعذر الوصول للـ API من المتصفح (قد يكون CORS): ${e.message}`);}const ms=Math.round(performance.now()-t);addNode({shape:'rounded',kind:'card',label:`API ${res.status}`,note:`${ms}ms\n${body.slice(0,900)}`,url:u,source:'API Test',color:res.ok?'green':'pink',confidence:1},'اختبار API');return{status:res.status,ms,body};}
async function runAgentRoute(route,text){
  if(route==='web'){const q=text.replace(/^(?:ابحث|بحث عن|research|search web|دور على)\s*/i,'');const r=await groundedSearch(`ابحث عن: ${q}. استخدم مصادر موثوقة وحديثة، ميّز الحقائق عن الاستنتاجات، وأعطني تفاصيل تكفي لبناء خريطة بصرية.`);await researchToCanvas(q,r.text,r.sources);return;}
  if(route==='deep'){await runDeepResearch(text.replace(/بحث عميق|deep research/ig,'').trim()||text);return;}
  if(route==='plan'){await runDeepResearch(text,'plan');return;}
  if(route==='github'){await runGithubSearch(text.replace(/github|جيت ?هب/ig,'').trim()||text);return;}
  if(route==='images'){await runImageSearch(text.replace(/صور|صورة|مراجع بصرية/ig,'').trim()||text);return;}
  if(route==='url'){const u=(text.match(/https?:\/\/[^\s]+/i)||[])[0];if(!u)throw new Error('ما لقيت رابط');const r=await urlContextRead(u,text);await researchToCanvas(safeHost(u),r.text,r.sources,'ركز على محتوى الرابط نفسه.');return;}
  if(route==='news'||route==='competitors'||route==='compare-tools'){const prompt=route==='news'?`ابحث عن أحدث الأخبار والتطورات المتعلقة بـ ${text} مع التواريخ والمصادر.`:route==='competitors'?`ابحث عن المنافسين والشركات والمنتجات المتعلقة بـ ${text}. قارن الميزات والأسعار والتموضع.`:`قارن الأدوات المذكورة في: ${text}. استخدم التوثيق والمصادر الرسمية قدر الإمكان: السعر، السهولة، القيود، ومتى نختار كل واحدة.`;const r=await groundedSearch(prompt);await researchToCanvas(text,r.text,r.sources,route==='compare-tools'?'استخدم عقد مقارنة وجدول عند الحاجة.':'');return;}
  if(route==='cost'){const r=await codeExecution(`حلل واحسب التكاليف المطلوبة لهذا الطلب بدقة. استخدم Python للحسابات إذا كانت هناك أرقام وافتراضات، واذكر الافتراضات بوضوح: ${text}`);await researchToCanvas('التكلفة',`${r.text}\nالكود:\n${r.code}\nالناتج:\n${r.output}`,[],'أنشئ بطاقات تكلفة وافتراضات ومجموع نهائي.');return;}
  if(route==='code'){const r=await codeExecution(text);addNode({shape:'sticky',kind:'card',label:'Code Runner',note:`${r.code}\n\n${r.output||r.text}`.slice(0,1200),color:'purple',icon:'⌘'},'تشغيل كود');return;}
  if(route==='api'){await runApiTestFromText(text);return;}
  if(route==='toolfinder'){const r=await groundedSearch(`اختر أفضل الأدوات والخدمات الحالية لهذا الاحتياج: ${text}. قارن البدائل، السعر، القيود، سهولة التنفيذ، ولماذا نختار كل أداة. استخدم المصادر الرسمية قدر الإمكان.`);await researchToCanvas('Tool Finder',r.text,r.sources,'أنشئ خريطة stack تقني: كل أداة مع سبب الاختيار والبدائل والتكلفة ودورها.');return;}
  if(route==='docs'){const r=await groundedSearch(`ابحث عن التوثيق الرسمي المتعلق بهذا الطلب: ${text}. أعط روابط الوثائق الرسمية المباشرة وأهم النقاط.`);let combined=r.text,sources=r.sources;if(r.sources[0]?.url){try{const d=await urlContextRead(r.sources[0].url,text);combined+=`\n\nقراءة التوثيق:\n${d.text}`;sources=[...sources,...d.sources];}catch{}}await researchToCanvas('Documentation',combined,sources,'ركز على خطوات الربط، القيود، الأمثلة، والحقول المهمة.');return;}
  if(route==='compare-canvas'){const sel=selectedNodes();const target=sel.length>=2?JSON.stringify(sel.slice(0,6)):JSON.stringify(compactCanvasState());const p=await askGemini(`قارن العناصر/الفروع التالية بوضوح. أنشئ عقدة table للمقارنة وعقدة توصية نهائية مع الأسباب. البيانات: ${target}`);executeActions(sanitizeActions(p));return;}
  if(route==='convert'){if(/جدول|table/i.test(text)){convertCanvasToTable();return;}if(/timeline|زمني/i.test(text)){applyLayout('timeline');return;}if(/flowchart/i.test(text)){applyLayout('flow',innerWidth<650?'vertical':'horizontal');return;}if(/خريطة|mind map/i.test(text)){applyLayout('radial');return;}const p=await askGemini(text);executeActions(sanitizeActions(p));return;}
  if(route==='update-plan'){const ctx=state.researchContext;if(!ctx)throw new Error('ماكو بحث سابق حتى أحدثه');await runDeepResearch(ctx.title,'plan');return;}
  if(['critic','summarize','expand','ask-canvas'].includes(route)){const target=route==='expand'&&state.selectedIds.size?`العنصر المحدد: ${JSON.stringify(selectedNodes()[0])}`:'';const prompt=route==='critic'?'راجع اللوحة الحالية نقدياً: اكتشف النواقص، التناقضات، المخاطر والافتراضات ثم أضف عقد تحسين واضحة. اجمع المتشابه إذا كان هذا يحسن الفهم.':route==='summarize'?'لخص اللوحة الحالية إلى عقدة ملخص و5 نقاط أساسية مرتبطة بها.':route==='expand'?`وسّع العنصر المحدد بتفاصيل عملية وفروع جديدة. ${target}`:`أجب عن طلب المستخدم اعتماداً على اللوحة الحالية ثم أضف جواباً بصرياً مناسباً: ${text}`;const p=await askGemini(prompt);executeActions(sanitizeActions(p));return;}
}
function friendlyError(err){const m=String(err?.message||err);if(/API key|API_KEY_INVALID|401|403/i.test(m))return'مفتاح الـ API غير صحيح أو ما عنده صلاحية';if(/429|quota|rate/i.test(m))return'وصلت حد الاستخدام المؤقت لـ Gemini';if(/404|not found/i.test(m))return'ما لقيت موديل متاح لهذا المفتاح';if(/abort/i.test(m))return'الطلب تأخر أكثر من اللازم';if(/Failed to fetch|NetworkError/i.test(m))return'مشكلة اتصال';return m.slice(0,160);}

function openPanel(el){closeSheets(false);el.classList.add('open');el.setAttribute('aria-hidden','false');backdrop.classList.add('open');backdrop.setAttribute('aria-hidden','false');}
function closeSheets(hideBackdrop=true){settingsPanel.classList.remove('open');utilitySheet.classList.remove('open');settingsPanel.setAttribute('aria-hidden','true');utilitySheet.setAttribute('aria-hidden','true');if(hideBackdrop){backdrop.classList.remove('open');backdrop.setAttribute('aria-hidden','true');}}
function openSettings(){openPanel(settingsPanel);} $('#settingsBtn').onclick=openSettings;$('#closeSettings').onclick=()=>closeSheets();backdrop.onclick=()=>closeSheets();
$('#toggleKey').onclick=()=>{const i=$('#apiKeyInput');i.type=i.type==='password'?'text':'password';$('#toggleKey').textContent=i.type==='password'?'إظهار':'إخفاء';};
$('#saveSettingsBtn').onclick=()=>{settings.apiKey=$('#apiKeyInput').value.trim();settings.model=$('#modelInput').value.trim()||'auto';settings.speechLang=$('#speechLanguage').value;settings.autoSendVoice=$('#autoSendVoice').checked;if(settings.apiKey){LS.setItem('gemini_api_key',settings.apiKey);SS.removeItem('gemini_api_key');}else{LS.removeItem('gemini_api_key');SS.removeItem('gemini_api_key');}LS.setItem('gemini_model',settings.model);LS.setItem('canvas_speech_lang',settings.speechLang);LS.setItem('canvas_auto_send_voice',String(settings.autoSendVoice));if(recognition)recognition.lang=settings.speechLang;modelPillText.textContent=settings.resolvedModel?prettyModelName(settings.resolvedModel):(settings.model==='auto'?'Gemini Flash':prettyModelName(settings.model));closeSheets();toast('تم الحفظ');};
$('#testApiBtn').onclick=async()=>{const old={...settings};settings.apiKey=$('#apiKeyInput').value.trim();settings.model=$('#modelInput').value.trim()||'auto';if(!settings.apiKey)return toast('اكتب المفتاح أولاً');setStatus('أختبر الاتصال…','thinking');try{await resolveModel(true);setStatus(`متصل · ${settings.resolvedModel}`,'ok');$('#modelHint').textContent=`الموديل الفعلي: ${settings.resolvedModel}`;toast('الاتصال شغال ✓');}catch(e){Object.assign(settings,old);setStatus('خطأ');toast(friendlyError(e));}};

function sheetHeader(title,sub=''){return `<div class="sheet-title-row"><div><strong class="sheet-title">${title}</strong>${sub?`<small class="sheet-subtitle">${sub}</small>`:''}</div><button class="close-sheet" data-action="close">×</button></div>`;}
function actionCard(action,icon,title,sub=''){return `<button class="sheet-action" data-action="${action}"><span class="ico">${icon}</span><b>${title}</b><small>${sub}</small></button>`;}
function openUtility(type){renderUtility(type);openPanel(utilitySheet);}
$('#moreBtn').onclick=()=>openUtility('menu');
